{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Donepezil, which shares the dimethoxybenzene, carbonyl, and basic amine features with the query, has an absolute oral bioavailability of 100% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Valbenazine, a tetrabenazine-related VMAT2 inhibitor with a dimethoxytetralin-like core, has an absolute oral bioavailability of approximately 49% in humans, supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Tetrabenazine has very low oral bioavailability (~5%), but this is driven by extensive first-pass ketone reduction, a liability absent in the query's lactam; thus it is contradictory evidence with limited transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query's lactam and basic amine features align better with high-bioavailability drugs (donepezil, valbenazine) than with tetrabenazine, whose low F depends on a reducible ketone absent in the query. Predicted high.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query or a close analog; all evidence molecules have low Morgan similarity (<0.4).",
    "The query contains four methoxy groups and a tertiary amine, which may increase first-pass metabolism; no evidence molecule matches this exact combination.",
    "The effect of the lactam versus ketone on metabolic stability is inferred, not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

